typedef struct
{
  float version;
  int type;
  char shortname[8];
  char desc[68];
  long int timestamp;
  int valid;
} saveInfo;

typedef struct
{
  int port;
  int slot;
  saveInfo *info;
  int maxItems;
  void *buffer;
  int size;
  void *iconData;
  int iconSize;
  bool overWrite;
  void(*progressCallback)(void *, int);
  void *userCallbackData;
} GameSaverThreadArgs;

typedef struct
{
  int status;
  void (*entry)(void *);
  void *stack;
  int stackSize;
  void *gpReg;
  int initPriority;
  int currentPriority;
  int attr;
  int option;
} ThreadParam;

extern int _gp;
extern int CreateThread(ThreadParam *);
extern int StartThread(int, void *);

class GenericGameSaver
{
public:
  unsigned char dastack[0x2000+17] __attribute__ ((aligned(16)));
  char before_fInfo[0xa3f];
  saveInfo fInfo;
  GameSaverThreadArgs *arg;

  int isFileValid(int port, int slot, saveInfo s);
  static void readFileHelper(void *args);

  void readFile(int port, int slot,
                void *buffer, int maxSize,
                void (*progressCallback)(void *, int),
                void *userCallbackData);
};

void GenericGameSaver::readFile(int port, int slot,
                               void *buffer, int maxSize,
                               void (*progressCallback)(void *, int),
                               void *userCallbackData)
{
  ThreadParam th_param;
  int dathread;
  th_param.entry = GenericGameSaver::readFileHelper;
  th_param.stack = this->dastack+16;
  th_param.stackSize = 0x2000;
  th_param.initPriority = 1;
  th_param.gpReg = &_gp;
  th_param.option = 0;
  arg->userCallbackData = userCallbackData;
  arg->progressCallback = progressCallback;
  arg->buffer = buffer;
  arg->size = maxSize;
  arg->info = &fInfo;
  arg->port = port;
  arg->slot = slot;

  arg->info->valid = isFileValid(arg->port, arg->slot, *arg->info);

  if (arg->info->valid < 0)
  {
    progressCallback(userCallbackData, arg->info->valid);
    return;
  }

  dathread = CreateThread(&th_param);
  if (dathread < 0)
  {
    progressCallback(userCallbackData, -1);
    return;
  }
  if (StartThread(dathread, arg) < 0)
  {
    progressCallback(userCallbackData, -1);
    return;
  }
}
